sys_script_include.script:
var cesyCcfHelper = Class.create();
cesyCcfHelper.prototype = {
    initialize: function() {},

    migrateToCommnConnFramework: function() {

        var propertiesArr = [];

        propertiesArr.push({
            name: "x_cesy_service_gr.username",
            value: "admin2"
        });

        propertiesArr.push({
            name: "x_cesy_service_gr.client.id",
            value: "945b992c2706407aa415a02bee293a24"
        });

        propertiesArr.push({
            name: "x_cesy_service_gr.endpoint",
            value: "" // to be filled later
        });

        propertiesArr.push({
            name: "x_cesy_service_gr.password",
            value: "" // should NOT stay like this in production
        });

        propertiesArr.push({
            name: "x_cesy_service_gr.client.secret",
            value: "" // should NOT stay like this in production
        });

        propertiesArr.push({
            name: "x_cesy_service_gr.api.token",
            value: ""
        });

        var ccFHelper = new x_cesy_service_gr.cesyCcfHelper();

        ccFHelper.createCommonConnAndMapTheDetails(
            '43a002accf8b721070a276d42d851cb2', // aliasId
            'x_cesy_service_gr', // scope
            '26239835cf57365050fef7a13d851c95', // data source
            propertiesArr
        );
    },

    // ================= CORE LOGIC =================

    createCommonConnAndMapTheDetails: function(aliasId, scopeId, dsSysID, propertiesArr) {

        var sysAliasGr = new GlideRecordSecure('sys_alias');

        if (sysAliasGr.get(aliasId)) {

            var common_connection_id = this.createCommonConnectionRecord(
                sysAliasGr.getValue('name'),
                sysAliasGr.getUniqueValue()
            );

            this.createCommonConnectionDataSourceRecord(common_connection_id, dsSysID);

            var scheduledImportGr = new GlideRecordSecure('scheduled_import_set');
            scheduledImportGr.addQuery('data_source', dsSysID);
            scheduledImportGr.query();

            if (scheduledImportGr.next()) {
                this.createCommonConnectionScheduledImportRecord(
                    common_connection_id,
                    scheduledImportGr.getUniqueValue()
                );
            }

            for (var i = 0; i < propertiesArr.length; i++) {
                var propertyObj = propertiesArr[i];

                this.createCommonConnectionPropertyRecord(
                    common_connection_id,
                    propertyObj.name,
                    propertyObj.value
                );
            }

        } else {
            gs.error("Connection alias not found: " + aliasId);
        }
    },

    createCommonConnectionRecord: function(name, conAliasSysId) {

        var ccf_connection = new GlideRecordSecure('sn_cmdb_int_util_service_graph_connection');

        ccf_connection.addQuery('connection_alias', conAliasSysId);
        ccf_connection.query();

        if (!ccf_connection.next()) {
            ccf_connection.initialize();
            ccf_connection.name = name;
            ccf_connection.connection_alias = conAliasSysId;
            ccf_connection.insert();
        }

        return ccf_connection.getUniqueValue();
    },

    createCommonConnectionDataSourceRecord: function(connectionId, dsSysId) {

        var gr = new GlideRecordSecure('sn_cmdb_int_util_service_graph_connection_data_source');

        gr.addQuery('sn_cmdb_int_util_service_graph_connection', connectionId);
        gr.addQuery('sys_data_source', dsSysId);
        gr.query();

        if (!gr.next()) {
            gr.initialize();
            gr.sn_cmdb_int_util_service_graph_connection = connectionId;
            gr.sys_data_source = dsSysId;
            gr.insert();
        }
    },

    createCommonConnectionScheduledImportRecord: function(connectionId, siSysId) {

        var gr = new GlideRecordSecure('sn_cmdb_int_util_service_graph_connection_scheduled_data_import');

        gr.addQuery('sn_cmdb_int_util_service_graph_connection', connectionId);
        gr.addQuery('scheduled_import_set', siSysId);
        gr.query();

        if (!gr.next()) {
            gr.initialize();
            gr.sn_cmdb_int_util_service_graph_connection = connectionId;
            gr.scheduled_import_set = siSysId;
            gr.insert();
        }
    },

    createCommonConnectionPropertyRecord: function(connectionId, name, value) {

        var gr = new GlideRecordSecure('sn_cmdb_int_util_service_graph_connection_property');

        gr.initialize();
        gr.property = name;
        gr.value = value;
        gr.sn_cmdb_int_util_service_graph_connection = connectionId;
        gr.insert();
    },

    getCCFPropertiesAsMap: function(ccf_connection_sysid) {

        var map = {};

        var gr = new GlideRecordSecure('sn_cmdb_int_util_service_graph_connection_property');
        gr.addQuery('sn_cmdb_int_util_service_graph_connection', ccf_connection_sysid);
        gr.query();

        while (gr.next()) {
            map[gr.property.toString()] = gr.value.toString();
        }

        return map;
    },

    getCCFConnectionFromAlias: function(aliasId) {

        var gr = new GlideRecordSecure('sn_cmdb_int_util_service_graph_connection');
        if (gr.get('connection_alias', aliasId)) {
            return gr.getUniqueValue();
        }
		return false;
    },

    testConnection: function(gr) {

        // Reset status
        gr.status = "Pending";
        gr.message = "";
        gr.suggestion = "";
        gr.update();

        try {

            var inputs = {};
            inputs['connectionAlias'] = gr.connection_alias;

            var result = sn_fd.FlowAPI.getRunner()
                .action('x_cesy_service_gr.test_connection')
                .inForeground()
                .withInputs(inputs)
                .run();

            var outputs = result.getOutputs();

            var statusCode = outputs.statusCode;
            var responseBody = outputs.body;

            gr.status_code = statusCode;

            if (statusCode == 200) {
                gr.status = "success";
                gr.message = "Connection successful";
                gr.suggestion = "";

            } else if (statusCode == 401) {
                gr.status = "error";
                gr.message = "Unauthorized";
                gr.suggestion = "Check API token (Bearer format)";

            } else if (statusCode == 403) {
                gr.status = "error";
                gr.message = "Forbidden";
                gr.suggestion = "Check API permissions/scopes";

            } else if (statusCode == 404) {
                gr.status = "error";
                gr.message = "Endpoint not found";
                gr.suggestion = "Verify endpoint URL";

            } else {
                gr.status = "error";
                gr.message = responseBody;
                gr.suggestion = "Unexpected error — check logs";
            }

        } catch (ex) {

            gr.status = "error";
            gr.message = ex.getMessage();
            gr.suggestion = "Execution failure — check Flow and logs";
        }

        gr.update();
    },

    type: 'cesyCcfHelper'
};
